contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: call SetMinSum twice with possibly different values.
    // Assert that MinSum equals the first value (i.e., second call cannot change it).
    function run(uint firstVal, uint secondVal) public {
        // Preconditions to avoid trivial identical inputs
        require(firstVal != secondVal);

        // First call: should succeed on both P and M
        c.SetMinSum(firstVal);

        // Second call: on P it should revert due to nonReentrant_ locked_ check (or initialized guard);
        // but we still perform it to observe behavior. Since state-changing calls must be top-level,
        // we invoke it and then read MinSum.
        // To handle possible revert on P, we call it inside a low-level call capturing the success flag.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", secondVal));

        // Read the publicly observable MinSum
        uint mm = c.MinSum();

        // On P, the second call cannot change MinSum, so it must equal firstVal.
        // On M, SetMinSum is callable again and will set MinSum to secondVal, violating this assert.
        assert(mm == firstVal);
    }

    // allow receiving Ether if needed by tests (not used here)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need caller to have some funds to call Collect if Collect expects payable; caller's balance must cover amount.
    function run(uint am) public payable {
        require(address(this).balance >= am && am > 0);
        // Read MinSum before calling Collect
        uint before = c.MinSum();
        // Call that in the counterexample order
        c.Collect(am);
        // Read MinSum after the call
        uint after = c.MinSum();
        // General rule: Collect does not modify MinSum, so before == after
        assert(before == after);
    }

    receive() external payable {}
}

