contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll try to detect whether a call sequence starting with Collect can lead to MinSum changing
    // via a reentrant SetMinSum during Collect's external call. To observe reentrancy we require that
    // c is not yet initialized (so SetMinSum is allowed) and that MinSum has some initial value.

    function run(uint sendAmount, uint collectAmount) public payable {
        require(address(this).balance >= sendAmount);
        // Preconditions: contract not initialized yet so SetMinSum would be callable if reentered
        require(c.intitalized() == false);

        uint beforeMin = c.MinSum();

        // Call Collect which in the mutant could allow reentrancy to call SetMinSum and change MinSum.
        c.Collect{value: sendAmount}(collectAmount);

        uint afterMin = c.MinSum();

        // In the original (with nonReentrant_), Collect cannot cause a reentrant SetMinSum to run,
        // so MinSum must remain equal to its prior value if Initialized is still false.
        // This asserts that MinSum didn't change as a result of the Collect call.
        assert(beforeMin == afterMin);
    }

    // accept ether so this contract can fund calls
    receive() external payable {}
}

