pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: initialMin (value to set), deposit (funds to put), collectAmt (amount to collect), lockTime
    function testFuzz_property(uint256 initialMin, uint256 deposit, uint256 collectAmt, uint256 lockTime) public {
        // keep ranges reasonable but wide
        initialMin = bound(initialMin, 1, type(uint256).max);
        deposit = bound(deposit, 1, 1 ether);
        collectAmt = bound(collectAmt, 1, 1 ether);
        lockTime = bound(lockTime, 0, 1000);

        // deploy an attacker that will reenter Collect and call SetMinSum
        Attacker attacker = new Attacker(address(c));

        // initialize contract state: set MinSum via nonReentrant protected call
        // must call SetMinSum before Initialized() is set to true
        // call as externally owned account
        address setter = address(0xABCD);
        vm.deal(setter, 0);
        vm.prank(setter);
        c.SetMinSum(initialMin);

        // register log file to some address (can be zero address to keep simple)
        vm.prank(setter);
        c.SetLogFile(address(0));

        // now fund attacker and perform Put (Use attacker contract as the caller so it can reenter)
        vm.deal(address(attacker), deposit + 1 ether);
        // attacker will put deposit and set lockTime
        attacker.prepare{value: deposit}(lockTime);

        // remember MinSum before Collect
        uint256 before = c.MinSum();

        // attempt Collect from attacker; attacker will reenter and call SetMinSum to a different value
        // We use try/catch around external call to observe behavior; but Collect is external and we call via attacker
        bool ok;
        try attacker.triggerCollect{value: 0}(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: on the correct contract, MinSum must equal the value we set earlier (never changed during Collect)
        // The bug removes nonReentrant_ and allows reentrant SetMinSum to mutate MinSum during Collect; thus this assertion will fail on buggy mutant for some fuzz inputs
        assertTrue(c.MinSum() == before);
    }
}

// Minimal re-entrant attacker: it will call Put to deposit funds, then call Collect; in its fallback (receive) it will reenter and call SetMinSum
contract Attacker {
    C target;
    bool attacked;

    constructor(address _t) {
        target = C(_t);
        attacked = false;
    }

    // prepare deposit and set lockTime via Put
    function prepare(uint256 lockTime) external payable {
        // call Put with value forwarded
        target.Put{value: msg.value}(lockTime);
    }

    // trigger Collect; this will cause the target to send Ether to this contract, invoking receive -> reentrancy
    function triggerCollect(uint256 amt) external payable {
        target.Collect(amt);
    }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            // reenter SetMinSum to change MinSum during Collect
            // choose different value than current: set to 1
            target.SetMinSum(1);
        }
    }
}

