pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker deposit amount and a newMin value to try to set during reentrancy
    function testFuzz_property(uint128 deposit, uint128 newMin) public {
        // keep amounts reasonable but wide
        uint256 amt = bound(uint256(deposit), 1, 1 ether);
        uint256 desired = uint256(newMin);

        // deploy attacker which will reenter Collect and call SetMinSum(desired)
        Attacker attacker = new Attacker(address(c), desired);

        // fund attacker so it can call Put/Collect and receive/send
        vm.deal(address(attacker), amt);

        // initialize contract: set log file to attacker (harmless) and set MinSum to a sentinel value via non-reentrant path
        // Use prank from EOA to call SetLogFile and SetMinSum once before Initialized is called
        address admin = address(0xBEEF);
        vm.deal(admin, 1 ether);
        vm.prank(admin);
        c.SetLogFile(address(attacker));

        // set an initial MinSum; this call is protected by nonReentrant_ in the reference
        vm.prank(admin);
        c.SetMinSum(42);

        // mark initialized so further SetMinSum/SetLogFile should revert on normal calls
        vm.prank(admin);
        c.Initialized();

        // attacker puts funds by sending to contract (calls fallback -> Put)
        // attacker will later call Collect and reenter
        attacker.deposit{value: amt}();

        // record MinSum before triggering Collect
        uint256 before = c.MinSum();

        // attacker triggers Collect which in fallback/reentrancy will call SetMinSum on c
        // call Collect with amount = amt to satisfy balances
        attacker.attackCollect{value: 0}(amt);

        // after the Collect completes, reference contract must still have same MinSum
        // the mutant (without nonReentrant_) can allow MinSum to change during reentrancy
        assertTrue(c.MinSum() == before);
    }
}

// Attacker contract: will call Put by sending ETH to C (via fallback), then call Collect,
// and during receiving funds in reentrancy will call SetMinSum on C to attempt to change MinSum.
contract Attacker {
    C target;
    uint256 public toSet;

    constructor(address _t, uint256 _toSet) payable {
        target = C(_t);
        toSet = _toSet;
    }

    // deposit into target by calling fallback which routes to Put(0)
    function deposit() external payable {
        // send ETH directly to target to trigger fallback -> Put(0)
        (bool s, ) = address(target).call{value: msg.value}("");
        require(s);
    }

    // trigger Collect; this will make the target send ETH back to this contract which will execute receive()
    function attackCollect(uint256 _am) external payable {
        // call Collect as this contract
        target.Collect(_am);
    }

    // receive will be executed when target sends funds; this is the reentrant point
    receive() external payable {
        // attempt to call SetMinSum during reentrancy
        // This will succeed on the mutant (no nonReentrant_), and revert on normal if Initialized blocks or nonReentrant_ prevents
        // Use low-level call to ignore revert if it fails
        (bool ignored, ) = address(target).call(abi.encodeWithSignature("SetMinSum(uint256)", toSet));
        ignored;
    }
}

