pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: attacker deposit amount and newMin proposed by attacker during reentrancy
    function testFuzz_property(uint256 deposit, uint256 newMin) public {
        // keep deposit in a reasonable range but wide
        deposit = bound(deposit, 1, 1 ether);

        // deploy attacker that will re-enter and call SetMinSum during Collect
        Attacker atk = new Attacker(address(c), newMin);

        // fund attacker so it can call Put via fallback and Collect will send value to attacker
        vm.deal(address(atk), deposit);

        // register Log file to a benign log contract so Put/Collect don't revert due to zero address
        LogHelper log = new LogHelper();
        c.SetLogFile(address(log));

        // set an initial MinSum to a known value
        c.SetMinSum(12345);

        // ensure contract initialized flag remains false so SetMinSum is callable
        // now have attacker Put funds (via calling Put) so it has balance to Collect
        vm.prank(address(atk));
        // call Put with some lock time; attacker will have funded deposit so this succeeds
        atk.callPut{value: deposit}(0);

        // record MinSum before Collect
        uint256 before = c.MinSum();

        // attacker will attempt to Collect; during the low-level send in Collect, its fallback/receive will re-enter SetMinSum
        // ensure attacker has msg.sender context when calling Collect
        vm.prank(address(atk));
        // call Collect on behalf of attacker; if it reverts or not we capture outcome by try/catch per rules
        bool ok;
        try atk.callCollect(address(c), deposit) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect completes (or reverts), the reference contract guarantees MinSum unchanged for all inputs.
        // The mutant that removed nonReentrant_ on SetMinSum can have MinSum changed by the re-entrant SetMinSum call.
        assertTrue(c.MinSum() == before);
    }
}

// Minimal attacker contract that re-enters during Collect's external send
contract Attacker {
    address public target;
    uint256 public newMin;
    bool public reentered;

    constructor(address _t, uint256 _newMin) payable {
        target = _t;
        newMin = _newMin;
        reentered = false;
    }

    // helper to call Put on C
    function callPut(uint _lockTime) external payable {
        C(target).Put{value: msg.value}(_lockTime);
    }

    // helper to call Collect on C; we call Collect from this contract so fallback/receive executes when C sends Ether
    function callCollect(address _c, uint _am) external {
        C(_c).Collect(_am);
    }

    // fallback will be invoked when C sends Ether; perform re-entrancy by calling SetMinSum once
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to change MinSum during Collect's external call
            C(target).SetMinSum(newMin);
        }
    }
}

// Minimal benign Log helper so C.SetLogFile can point to a contract with AddMessage
contract LogHelper {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    function AddMessage(address _adr,uint _val, string memory _data) public {
        Message memory m = Message({Sender:_adr, Data:_data, Val:_val, Time:block.timestamp});
        History.push(m);
    }
}

