contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters:
    // - uint256 sendAmount: Ether that attacker will send into Put via fallback when reentering
    // - uint256 newMin: value attacker will attempt to set via SetMinSum during reentrancy
