        // Mark initialized so further SetMinSum/SetLogFile revert if called normally
        c.Initialized();

        // Prepare attacker that will reenter Collect and call SetMinSum (the mutated contract removed guard)
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), newMin);

        // Fund attacker and the actor who will deposit
        vm.deal(address(attacker), sendAmount);

        // Make the attacker deposit funds into C so Collect will be callable by attacker
        // attacker will call Put by sending ETH to C (fallback forwards to Put(0))
        attacker.deposit{value: sendAmount}(lockTime);

        // Record MinSum before Collect
        uint256 before = c.MinSum();

        // Call Collect from attacker; during Collect the attacker fallback/receive will reenter and call SetMinSum
        // We catch whether Collect succeeded or reverted, but the property is about MinSum preservation
        bool ok;
        try attacker.callCollect(uint256(1)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: in the correct contract, MinSum must remain equal to before for all inputs.
        // The mutant (removed nonReentrant_) can change MinSum during Collect for some inputs.
        assertTrue(c.MinSum() == before);
    }
}

// Minimal reentrant attacker: on receiving ETH in fallback it will call SetMinSum on target C
contract ReentrantAttacker {
    C immutable target;
    uint256 immutable newMin;
    bool public reentered;

    constructor(address _target, uint256 _newMin) {
        target = C(_target);
        newMin = _newMin;
        reentered = false;
    }

    // deposit into target by calling its fallback (which calls Put(0)) via plain transfer
    function deposit(uint256 lockTime) external payable {
        // call Put via fallback by calling target.Put directly with value
        // use low-level call to invoke Put(uint) as payable
        (bool s,) = address(target).call{value: msg.value}(abi.encodeWithSignature("Put(uint256)", lockTime));
        require(s);
    }

    // invoked by test to trigger Collect on target from this contract
    function callCollect(uint256 amt) external {
        // call Collect from this contract so that any fallback during the external call is within this contract
        target.Collect{value: 0}(amt);
    }

    // fallback will be called by target during Collect when target sends value to msg.sender
    // Reenter once to call SetMinSum on target
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // Attempt to call SetMinSum during Collect; in reference this is blocked by nonReentrant_
            // but mutant removed the guard, allowing change
            target.SetMinSum(newMin);
        }
    }
}

