            // success
        } catch {
            // ignore revert; Collect may revert depending on state but property concerns MinSum after call attempt
        }

        // Exactly one assertion: in the correct contract MinSum must equal before for all inputs.
        // The mutant (without nonReentrant_ on SetMinSum) can change MinSum during reentrant Collect for some inputs,
        // so the assertion will fail on the mutant for those inputs.
