// Minimal adversarial reentrant attacker that calls SetMinSum during Collect's external call
contract Attacker {
    address public target;
    uint256 public newMin;
    bool public reentered;

    constructor(address _target, uint256 _newMin) payable {
        target = _target;
        newMin = _newMin;
        reentered = false;
    }

    // helper to fund and perform an initial Put to have balance in C mapped to this attacker
    function fundAndPrepare() external payable {
        // call Put by sending ether to C (fallback in C calls Put(0))
        (bool s, ) = target.call{value: msg.value}("");
        require(s);
    }

    // fallback invoked by C when it sends ether to msg.sender during Collect; perform reentrant SetMinSum
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // call SetMinSum on the target during Collect
            (bool s, ) = target.call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));
            // ignore success; the point is to attempt the reentrant change
            s;
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: attempt to set MinSum before calling Initialized.
    // If P is used, this call should succeed; if M (mutant) is used, it will revert.
    function run(uint _val) public {
        // call that should succeed on original P
        c.SetMinSum(_val);

        // Observe outcome via public getter MinSum
        uint observed = c.MinSum();

        // The distinguishing property: after the call, MinSum equals the provided value.
        // This holds for P (SetMinSum accepted when not initialized) and is violated by M
        // because M would have reverted and not updated MinSum.
        assert(observed == _val);
    }
}

