contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Caller will provide parameters: amount to attempt to Collect (am), and
    // we also provide a value to ensure the caller has enough balance if needed.
    function run(uint _am) public payable {
        // Precondition: ensure there is some MinSum value and contract is not initialized
        // We require that Initialized has not been called yet by checking behaviour: calling SetMinSum should NOT revert on original P.
        // To ensure this, attempt to set MinSum via a low-level call and require it succeeds.
        // However test may not call SetMinSum directly because it's part of c's external surface — it's allowed.
        // Use a fresh value and ensure it succeeds (on P it will, on mutant it would revert when not initialized — but we are crafting precondition for P).
