        } catch {
            ok = false;
        }
        require(ok == true);

        // Read MinSum before calling Collect
        uint before = c.MinSum();

        // Call Collect; this is the state-changing call after which difference is observable
        // No Ether is sent in this test (Collect is payable but not required for the rule)
        try c.Collect(_am) {
            // ignored
        } catch {
            // ignored, Collect may revert depending on balances/timings; still we observe MinSum afterward
        }

        uint after = c.MinSum();

        // On the original contract, if SetMinSum succeeded before (contract not initialized), Collect does not change MinSum.
        // Assert that MinSum remains equal to the value observed before Collect.
        assert(after == before);
    }

