        uint before = c.MinSum();
        // We only continue when it is 0 to capture the property that Collect doesn't raise it
        require(before == 0);
        // Call Collect as the provided caller would: use this contract as caller
        // Forward Ether amount to Collect
        c.Collect{value: amount}(amount);
        uint after = c.MinSum();
        // Assert that Collect did not increase MinSum
        assert(after == before);
    }
