contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No special precondition needed
        uint before = c.MinSum();
        // perform the call that differs between original and mutant
        c.Collect(0);
        uint after = c.MinSum();
        // General rule: Collect must not increase MinSum
        assert(after <= before);
    }
}

